import{_ as t,C as r,o,c as l,j as e,a as n,E as i,a6 as s}from"./chunks/framework.CnPv4DE1.js";const g=JSON.parse('{"title":"如何打造一个比99%的人都更出色的个人品牌","description":"","frontmatter":{"title":"如何打造一个比99%的人都更出色的个人品牌","originalTitle":"How To Build A Better Personal Brand Than 99% Of People","date":"2025-05-29","originalUrl":"https://thedankoe.com/letters/how-to-build-a-better-personal-brand-than-99-of-people/","minutes":13,"sourceHash":"322bcd7b44b5a35a6a313bf075043639cde2aafdba49b3ccde72a996fa9d26ac","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-build-a-better-personal-brand-than-99-of-people/"}]]},"headers":[],"relativePath":"letters/how-to-build-a-better-personal-brand-than-99-of-people.md","filePath":"letters/how-to-build-a-better-personal-brand-than-99-of-people.md"}'),h={name:"letters/how-to-build-a-better-personal-brand-than-99-of-people.md"};function d(u,p,b,c,m,f){const a=r("ArticleMeta");return o(),l("div",null,[p[0]||(p[0]=e("h1",{id:"如何打造一个比99-的人都更出色的个人品牌",tabindex:"-1"},[n("如何打造一个比99%的人都更出色的个人品牌 "),e("a",{class:"header-anchor",href:"#如何打造一个比99-的人都更出色的个人品牌","aria-label":'Permalink to "如何打造一个比99%的人都更出色的个人品牌"'},"​")],-1)),i(a),p[1]||(p[1]=s('<blockquote><p>大多数人不明白的是，“个人品牌”并不是一种商业模式。它是一种流量来源。它是一种信任机制。创始人打造个人品牌是为了给自己的创业公司获取用户。电商品牌利用用户生成内容（UGC）来销售实体产品。只要你有一个值得信任的个人品牌，你几乎可以卖任何东西——从咖啡豆到裸照。</p></blockquote><p>我从未想过自己会拥有一个个人品牌。</p><p>早在2016年左右，我想成为一名健身类YouTuber。</p><p>我和大学室友拍了些吃播挑战、健身训练和对镜说话的视频，效果甚微。我真希望自己没有删掉那些视频，但说实话，它们真的挺尴尬的。</p><p>但那并不是结局。</p><p>接下来，我沉迷于摄影、剪辑和数字艺术。</p><p>严格来说，“thedankoe”（我的用户名）就是在那时诞生的。我当时是大学学期之间暑假打工的救生员。我在琢磨要不要开一个Instagram账号发我的照片，我的同事们帮我一起想了这个名字。</p><p>我攒了一些粉丝，但最终精力耗尽了，因为我没办法一直靠猛灌兴奋剂和吃阿德拉（Adderall）来保证自己每天都能发出一张图。</p><p>所以那次也失败了。</p><p>但我真的、真的不想在大学毕业后去找一份工作。我从没想清楚自己长大后想成为什么样的人，但我确实想明白了一件事——我不想像大多数人那样活着：焦虑、情绪化、不健康。</p><p>我尝试过做3个电商品牌。一个卖极简钱包，一个卖蓝光眼镜，还有一个是一键代发（drop-shipping）的rave风格服饰。我还尝试了几个短命的项目，比如一个SEO代理和一个Facebook广告代理，这些都是我从买的课程里学来的。</p><p>这段时间线我自己都记得有点模糊了，因为在短短几年里发生了太多事，但我同时也在学编程，作为一种后备方案。我大学时上过一门编程入门课，挺喜欢的，觉得如果最终真得去找工作，这也能算是一条保底之路。</p><p>到这个阶段，我已经刷爆了第一张信用卡，欠了8000美元的债（对于一个和另外7个人合租、只为把房租压到最低的破产大学生来说，这可是一大笔钱），还在一家打印店打零工，而我做的那些生意一个都没成。</p><h3 id="为什么个人品牌拯救了我的人生" tabindex="-1">为什么个人品牌拯救了我的人生 <a class="header-anchor" href="#为什么个人品牌拯救了我的人生" aria-label="Permalink to &quot;为什么个人品牌拯救了我的人生&quot;">​</a></h3><p>我最终还是找了份工作。</p><p>那件我曾发誓永远不会做的事。</p><p>那是在亚利桑那州的一家网页设计公司。</p><p>但幸运的是，我很快就发现了大多数办公室工作的真相。我可以把所有工作都拖到最后一刻，直接复制粘贴网站模板，改改颜色、图片之类的，用一种还算过得去的质量完成工作，同时还能躲过雷达探测。我真是个糟糕的员工。</p><p>我知道，如果我在那份工作上待得太久，就会变得安逸。然后老婆、房贷和其他一切都会像打桩机一样把我砸进一个吞噬时间和金钱的责任深坑里。到那时想逃出来会越来越难。</p><p>所以我每天上班的头几个小时都在尝试做网页设计的自由职业。</p><p>简单来说，这奏效了，一年后我就能辞职了，但我没意识到自己给自己造了一个新的“朝九晚五”——不停地去联系客户，做那些我根本不在乎的项目。</p><p>就是在那时，社交媒体的力量向我显现出来了：</p><ul><li>人们只是在发关于自己知识和兴趣的内容，而我觉得自己也能写出类似他们发的那种东西</li><li>他们不需要不断地去联系客户，因为他们的内容会自动吸引客户</li><li>我看到一些网页设计师在卖数字产品，除了创建产品本身，几乎不需要额外的努力就能赚钱</li></ul><p>这几点全都符合我的需求。</p><p>但我已经试过了……</p><p>我的健身YouTube频道彻底失败了。我通过数字艺术积累了一些受众，但完全不知道如何把它变成一个可持续的收入来源。</p><p>不管怎样，我从那些失败的生意里学到了太多东西，我感觉自己有能力让它成功。</p><p>而如你所见，我确实做到了。</p><h2 id="打造一个比99-的人都更出色的个人品牌" tabindex="-1">打造一个比99%的人都更出色的个人品牌 <a class="header-anchor" href="#打造一个比99-的人都更出色的个人品牌" aria-label="Permalink to &quot;打造一个比99%的人都更出色的个人品牌&quot;">​</a></h2><blockquote><p>艺术家，从定义上来说，就是真实的。企业家也是真实的。谁会成为埃隆·马斯克（Elon Musk）？谁会成为杰克·多西（Jack Dorsey）？这些人都是真实的，他们创造的商业和产品也真实地反映了他们的欲望和能力。</p><p><em>《通过真实性摆脱竞争》——纳瓦尔（Naval）</em></p></blockquote><p>让我们加快一点节奏。</p><p>你来到这里，是因为你有兴趣或技能，想把它们变成一种能抵御未来变化的收入来源。</p><p>但你不想变成一个空洞的人类躯壳。</p><p>你不想被装进一个盒子里。</p><p>你不想把自己打造成另一个朝九晚五。</p><p>我想直接切入你现在能做的、<em>影响力最大</em>的那些事情。</p><p>那些大多数新手根本不知道、或者一眼掠过的东西。</p><p>如果你只专注于这些事情，我向你保证，你不会像那些因为得不到结果而放弃的人一样落得那样的结局。</p><p>先把你的细分领域放到一边。</p><p>先把你的简介、横幅之类的东西放到一边。</p><p>这些东西很重要，但也有很多人连简介都没写、头像都是空白的，照样做得很好。</p><p><em>你的内容，以及你在足够长的时间里持续发布的那些想法的质量，才是打造一个让人不由自主信任的品牌的关键所在。</em></p><p>这就是你整个商业策略。</p><p>信任。</p><p>金钱是信任的一种衡量方式。</p><p>我要教给你的，是我称之为“信任矩阵”（The Trust Matrix）的东西：</p><ul><li><strong>增长（Growth）</strong>——做那些“有效的事”来吸引人们。</li><li><strong>真实性（Authenticity）</strong>——表达你的核心信念。</li><li><strong>权威性（Authority）</strong>——展示你的专业能力。</li></ul><p>自2020年我第一次谈到这个框架以来，市面上出现了不少衍生版本，但我已经把它打磨得比以前更加清晰了。</p><p>如果你能把这3点都做到位，你的品牌就将无可撼动。</p><p>之后，我们会谈谈如何把这个品牌基础转化为一种更轻松地创造收入的方式。</p><h3 id="增长——锻炼你-从想法到执行-的肌肉" tabindex="-1">增长——锻炼你“从想法到执行”的肌肉 <a class="header-anchor" href="#增长——锻炼你-从想法到执行-的肌肉" aria-label="Permalink to &quot;增长——锻炼你“从想法到执行”的肌肉&quot;">​</a></h3><p>我在成功的创作者身上注意到一种模式：</p><p>当他们察觉到一个处于“表现力”和“兴奋感”交汇点上的想法时，他们会立刻放下手头正在做的一切，把它写下来。</p><p>这些想法通常会在他们散步时、听有声书或视频时、阅读书籍或“有分量”的内容（不是那种让脑子变糊的社交媒体帖子）时，或者与他人交谈时突然出现。</p><p>这里有两个要素。</p><ul><li><strong>表现力（Performance）</strong>——他们知道如何用一种引人入胜的方式表达想法。这些想法本身具有“表现良好”的潜力。</li><li><strong>兴奋感（Excitement）</strong>——他们对理解这个想法、或用自己的方式表达它有着真正的兴趣。他们把自己的品牌看作是这些想法笔记的集合。</li></ul><p>当你知道<em>如何用引人入胜的方式表达一个想法</em>，并且<em>想去写它</em>时，一切都能成为想法的来源。</p><p>大多数人苦于想不出值得写的东西，原因就是这两点。他们的思维没有被训练得足够善于表达，也没有摄入处于自己理解边界的信息。</p><p>对你的增长最有益的一件事，就是把那些高表现的帖子结构当作训练轮，来锻炼你的表达能力。</p><ul><li>拿出一本笔记本，或打开一个笔记软件</li><li>写下5-10位你欣赏其表达能力的作家、思想者或创作者</li><li>接下来一周，每天花1小时浏览他们的社交账号</li><li>找出他们的“异常值”——那些互动量至少是其他帖子2倍的帖子</li><li>把它们截图，或记在你的笔记软件里</li></ul><p>你不是作为一个消费者去阅读这些想法，而是像一名科学家一样去研究它们。</p><p>当你收集到至少20-30个代表你想采用的表达方式的帖子后，去拆解<em>为什么这些帖子效果这么好。</em></p><p>为每个帖子写下3-5条要点，说明它为什么能抓住注意力、为什么人们会与之互动、他们用了什么心理策略等等。</p><p>更好的方法是，用这个提示词：</p><blockquote><p>对这条社交帖子做一个全面分析。整体想法、句子结构、用词选择。分析为什么人们会与它互动、为什么它效果这么好、用了什么心理策略，以及我如何能用我自己的想法，一步步复刻这种风格。</p><p>[粘贴社交帖子]</p></blockquote><p>简而言之，你在拆解那些<em>已经被验证过</em>的想法为什么效果这么好。当你练习用一种能让人停止滑动、几乎逼着读者去吸收这个想法的方式来写作时，增长便是一个自然的副产品。</p><h3 id="真实性——核心信念吸引对的人" tabindex="-1">真实性——核心信念吸引对的人 <a class="header-anchor" href="#真实性——核心信念吸引对的人" aria-label="Permalink to &quot;真实性——核心信念吸引对的人&quot;">​</a></h3><p>到目前为止，经过练习，你已经知道如何把任何一个想法变成一条让人无法忽视的社交帖子。</p><p>但人们追随的不是想法，而是分享想法的人。</p><p>两个人可以写出完全相同的内容，但人们对这条帖子的感知会截然不同。</p><p>拿詹姆斯·克利尔（James Clear）和街上随便一个人相比。</p><p>他们俩都发了一条推文：“习惯对你有好处。”</p><p>数千万人知道詹姆斯·克利尔是谁。他们知道他的故事。他们读过他那本关于习惯的书。他们与他之间存在一种深刻却间接的关系。</p><p>大多数看到这条詹姆斯·克利尔推文的人，会点赞、转发，仅仅是因为他们认同这句话。而正是“詹姆斯说了这句话”这一事实，把他其他的想法也一并带进了这条帖子里。</p><p>但如果一个随便的人发了同样简单的话，人们只会无视它，或者评论一句：“是啊，废话。”</p><p>这里有3个要点：</p><ul><li><strong>被关注的时间（Time under attention）</strong>——人们给你的关注越多，尤其是通过文章、书籍、视频这类长内容，他们就越会把你的帖子放到你其余想法的整体背景中去理解。</li><li><strong>价值观的一致性（Alignment of values）</strong>——当人们知道你是谁、你从哪里来、你的立场是什么时，他们会与你整体的想法建立起更深的关系。</li><li><strong>真实的两极分化（Authentic polarization）</strong>——“如果你被所有人喜欢，那你其实不被任何人真正喜欢。”你需要给人们理由去强烈反对你，从而也强烈认同你。这是把自己真实展现出来时最难的部分。</li></ul><p>这一点不需要太多解释。</p><p>你可以直接观察到，对于那些你认同其故事和核心信念的创作者，你会感觉到一种更强的连接。如果有人给你一个来自某个随便品牌的产品，和一个来自你喜爱的创作者的类似产品，让你二选一购买，你很可能会选那位创作者的。</p><p>我们该如何在自己的品牌中复刻这一点呢？</p><p>我们需要在内容中经常呈现我们的<em>故事</em>和<em>核心信念</em>，既作为内容主题本身，也作为重新框定想法的一种方式。</p><p>作为一个内容主题，我可以谈谈自己是如何在7种不同的商业模式中失败的。</p><p>作为重新框定一个想法的方式，我可以谈论如何打造个人品牌（这已被验证过、且潜力巨大的话题），并通过从我自己的故事讲起，让这个话题变得独属于我。这正是我在这篇文章开头所做的事。</p><p>在我核心信念作为一个主题这方面，我可以谈谈我为什么认为数字产品是初学者最好的起点。我也可以透过“作为创作者”这个视角，重新框定经典的产品开发理念。</p><p>要把这件事做好：</p><ul><li>写下你曾处于的境地、是什么引发了变化，以及你现在所处的位置</li><li>针对你谈论的每一个主题或议题，列出你坚信不疑的核心原则</li></ul><p>仅仅坐着盯着空白屏幕很难做到这一点，所以我们可以借助 AI 来帮忙。</p><p>我创建了一个「故事与核心信念提取器」提示词，它会采访你、帮你集思广益，并生成一份完全符合你需求的草稿。</p><p><a href="https://app.kortex.co/public/document/9d77482b-0dd9-4dbc-829d-77f2d0364132" target="_blank" rel="noreferrer">保存这个提示词，读完这篇信件后使用。</a></p><p>这个提示词是「30天打造可盈利个人品牌」挑战的一部分，该挑战将于6月16日开始，<a href="https://stan.store/thedankoe/p/build-a-profitable-personal-brand-in-30-days" target="_blank" rel="noreferrer">如果你感兴趣的话可以了解更多。</a></p><h3 id="权威——说服性教育改变行为" tabindex="-1">权威——说服性教育改变行为 <a class="header-anchor" href="#权威——说服性教育改变行为" aria-label="Permalink to &quot;权威——说服性教育改变行为&quot;">​</a></h3><p>大多数创作者做的是教育类业务。</p><p>他们教授自己的技能和兴趣。</p><p>当然，你可以试着成为下一个大明星或 OnlyFans 模特，但请记住，我们的目标是产生某种积极影响并做有意义的工作。</p><p>问题是，已经有太多创作者在教你想教的东西了。你可以在 YouTube 上搜索任何技能，找到关于任何话题的大量视频。</p><p>这正是绊倒大多数初学者的地方。他们不相信别人有理由关注<em>他们</em>。既然已经有那么多人可以学习，为什么还要跟你学？</p><p>这里有两个解决方案。</p><p><strong>1）用新的视角来教</strong></p><p>和之前一样。</p><p>我可以在这篇信件中，从一个新的视角出发，通过讲述自己的个人故事来讲授个人品牌。</p><p>我喜欢用的另一种方法是通过一个新颖的想法来重新构建框架。</p><p>如果我持续研究并吸收那些有着绝妙想法的人的信息，最终会冒出类似 Naval 说的「想法是新的石油」以及「这一代人正在思维空间而非物理空间中致富」这样的观点。（这就是为什么让自己被优秀思想者包围很重要。）</p><p>然后，我可以<em>通过</em>这个想法引入个人品牌这个话题，这样会更有吸引力。</p><p><strong>2）说服那些不感兴趣的人</strong></p><p>我在过去几篇信件里反复谈这个，听起来像在鞭打一匹死马，但这一点非常重要，值得内化：</p><p>社交媒体上的大多数人并不是<em>有意识地</em>想要学习。如果他们是，他们会主动去搜索关于该主题的视频、课程或文章。而你，是被推送给社交媒体上<em>随机</em>的人的。你无法像在 Facebook 广告里输入兴趣和人群特征那样，控制谁会看到你的内容。</p><p>所以，<em>你需要把你的想法包装得广泛且有吸引力。</em></p><p>如果我想谈个人品牌，我不会直接给人们讲怎么选主题或写简介的指导。那太无聊了。这不会有足够的传播力，去触达新的受众。</p><p>我会以某种「如果你想要」（欲望）或「如果你不想要」（痛点）的句式开头，这样大多数人至少有机会<em>对我要说的内容产生兴趣</em>。</p><p>举个例子：</p><blockquote><p>如果你厌恶一辈子为别人的梦想打工的想法，那就去打造一个个人品牌。</p></blockquote><p>然后我可以接着列出打造个人品牌的好处、它的低风险程度，以及你几乎可以卖任何东西——从数字产品到软件再到实体产品。</p><p>在你的内容中，通过聚焦痛点、欲望和好处来掌控好奇心和欲望，这就是让人们对你所感兴趣的东西产生兴趣的方法。</p><h2 id="最好的变现方式" tabindex="-1">最好的变现方式 <a class="header-anchor" href="#最好的变现方式" aria-label="Permalink to &quot;最好的变现方式&quot;">​</a></h2><p>最好的变现方式就是任何方式。</p><p>它们真的都有效。</p><p>电子书、模板、训练营、教练辅导、付费通讯、赞助……</p><p>大多数人不理解的是，「个人品牌」本身不是一个生意。它是一个流量来源。创始人打造个人品牌是为了给自己的初创公司获取用户。电商品牌利用用户生成内容（UGC）来卖实体产品。如果你有一个值得信任的个人品牌，你几乎可以卖<em>任何东西</em>——从一袋咖啡到裸照都行。</p><p>那些没有个人品牌的人，需要快速建立信任，或者借助更深层的心理战术，通过直接反馈式营销来促成销售。他们需要尽可能快地从广告转化到成交。这就给潜在的不道德手段和唯快钱导向留下了空间。</p><p>由于我们是按照之前讲的「信任矩阵」来打造个人品牌的，你的处境已经相当不错了。</p><p>我本可以列出你能打造的每种产品类型的优缺点，但我想说的是：</p><p><em>你的第一个产品，打造时间不应该超过一周。</em></p><p>因为你手头可能早就有一个现成的产品了。</p><p>举个例子，来自 <a href="https://join.stan.store/thedankoe" target="_blank" rel="noreferrer">Stan</a>（一个替代你「简介链接」并承载产品的创作者商店）的 John Hu，找出了他当年帮他拿到高盛（Goldman Sachs）工作的旧简历，把它做成了一个模板。仅凭这个模板，他在分享职业建议的同时就赚到了最初的几千美元。（对了，多伦多的开发者们注意了，我们正在举办一个 Stan x Kortex 黑客松，奖金15,000美元。目标是打造一个能让人们为自己工作的创作者工具。<a href="https://hackai.ca/" target="_blank" rel="noreferrer">感兴趣的话在这里申请</a>，或者转发给你认识的人！）</p><p>你可以：</p><ul><li>录制一段30到60分钟的教学视频，讲解如何做好一件有影响力的事</li><li>找出一个曾帮你获得理想结果的旧资料，把它改造成模板</li><li>把一篇反响不错的社交帖子，改编成一份简短的指南或模板</li></ul><p>我们不是在这里赚大钱。</p><p>我们是在验证一个值得付费的想法。</p><p>先从大约10美元这样的定价开始。</p><p>如果你的转化率超过2.5%左右，那就可以考虑把它打造成更完整的产品。这样，你就不会浪费时间去做人们可能并不想要的东西。</p><p>事情真的可以这么简单。</p><p>我就说到这里，因为我已经发布过一篇<a href="https://thedankoe.substack.com/p/mega-guide-how-to-create-your-first" target="_blank" rel="noreferrer">打造数字产品的超级指南。</a></p><p>——Dan</p><p>当你准备好时，以下是我能帮到你的方式：</p><ul><li>「30天打造可盈利个人品牌」<a href="https://stan.store/thedankoe/p/build-a-profitable-personal-brand-in-30-days" target="_blank" rel="noreferrer">挑战将于6月16日开始</a>。如果你想要每天30到60分钟的任务，从而打造出你真正享受的事业基础，请在此之前报名。</li><li><a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> 是一款笔记与写作应用，搭配了25个以上的 AI 工作流（用于内容创作、营销和规划）。注册后即可与 YouTube 文字记录和 PDF 文件对话。</li></ul><hr><p><a href="/en/letters/how-to-build-a-better-personal-brand-than-99-of-people">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',137))])}const _=t(h,[["render",d]]);export{g as __pageData,_ as default};
